import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
targets = json.loads(Path('reference-targets.json').read_text())
answers = []

def add(number, paragraphs, reason, review, benefit=None, removed=None, repeal=None, checks=None):
    s = next(a for a in sources if a['number'] == number)
    a = {k:s[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    a.update(proposed_xml='\n'.join('<p>'+p+'</p>' for p in paragraphs), reason=reason,
             review_notes=review, status='rewrite_draft')
    if benefit is not None:
        a['benefit_review'] = benefit
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        a.update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if checks:
        a['reference_checks'] = [dict(target_key=k, view_sha256=targets['targets'][k]['view_sha256'], assessment=v) for k,v in checks.items()]
    answers.append(a)

